140	    // S0-3 (plan §4.2, §2.3 N1 TRM proxy): apply the ECC model to the just-
141	    // corrupted byte and report the outcome. Called AFTER the fault mask was
142	    // applied to *byte (data is now dirty). Decides the observable outcome:
143	    //   1-bit (popcount==1):
144	    //     SED            -> line invalidate+refetch (corrected) -> REVERT *byte
145	    //     SECDED         -> corrected -> REVERT *byte
146	    //     secded_poison  -> corrected -> REVERT *byte
147	    //     parity_interleaved -> parity detects 1-bit -> REVERT (re-fetch)
148	    //   2-bit (popcount==2):
149	    //     SED            -> >=2-bit silent (cannot detect) -> escape (Latent)
150	    //     SECDED         -> detected+contained (poison) -> leave dirty, mark poison
151	    //     secded_poison   -> poison+propagate -> leave dirty, mark poison
152	    //     parity_interleaved -> same-parity 2-bit silent -> escape (Latent)
153	    //   >=3-bit: all models beyond SECDED -> escape (Latent/SDC)
154	    //   None: raw escape.
155	    // Returns true if the corruption SURVIVED (data left dirty -> may escape
156	    // as SDC/Latent); false if corrected/reverted (data restored -> Masked/
157	    // Corrected).
158	    bool
159	    CHAOSCache::applyProtectionModel(uint8_t *byte, uint8_t orig, uint8_t mask,
160	                                     int byteOffset, Addr blockAddr)
161	    {
162	        if (protection_model == ProtectionModel::None) {
163	            stats->numRawEscaped++;
164	            if (write_log) {
165	                *(log_stream->stream()) << "  ProtectionModel=none: raw escape "
166	                    "(mask=" << std::bitset<8>(mask) << ")\n";
167	            }
168	            return true;  // data left dirty
169	        }
170	        int bits = __builtin_popcount(mask);
171	        bool survived = false;
172	        const char *outcome = "";
173	        if (bits == 1) {
174	            // All ECC models correct a single-bit flip -> REVERT the byte.
175	            *byte = orig;
176	            stats->numEccCorrected++;
177	            outcome = "EccCorrected";
178	            survived = false;
179	        } else if (bits == 2) {
180	            // SED/parity: cannot detect a same-parity 2-bit -> escape.
181	            // SECDED/secded_poison: detect+contain (poison) -> leave dirty.
182	            if (protection_model == ProtectionModel::SED ||
183	                protection_model == ProtectionModel::ParityInterleaved) {
184	                stats->numLatent++;
185	                outcome = "Latent";  // >=2-bit silent
186	                survived = true;
187	            } else {  // SECDED, SECDEDPoison
188	                stats->numDetectedContained++;
189	                outcome = "Poisoned: DetectedContained";  // contained DUE
190	                survived = true;  // dirty but contained (poisoned)
191	            }
192	        } else {  // >=3 bits: beyond SECDED
193	            stats->numLatent++;
194	            outcome = "Latent";  // >=3-bit, undetected escape
195	            survived = true;
196	        }
197	        if (write_log) {
198	            *(log_stream->stream()) << "  ProtectionModel=" << protectionModelToString(protection_model)
199	                << " bits=" << bits << " -> " << outcome
200	                << " (mask=" << std::bitset<8>(mask) << ")\n";
201	        }
202	        return survived;
203	    }
