241	    void
242	    CHAOSCache::injectFault()
243	    {   
244	        BaseTags* tags = getTags();
245	        unsigned blockSize = targetCache->getBlockSize();
246	        
247	        std::vector<CacheBlk*> validBlocks;
248	        
249	        tags->forEachBlk([&validBlocks](CacheBlk &blk) {
250	            if (blk.isValid()) {
251	                validBlocks.push_back(&blk);
252	            }
253	        });
254	        
255	        if (validBlocks.empty()) {
256	            warn("No valid block found\n");
257	        } else{
258	            // Directed target (report §六.3 'fixed-to'): if target_block_addr
259	            // is set, find the VALID block whose regenerated address matches
260	            // the block-aligned target. If not resident at injection time,
261	            // fall back to random with a log warning (honest: the fault did
262	            // not land on the directed block because it wasn't valid).
263	            CacheBlk* targetBlk = nullptr;
264	            bool directed_block = (target_block_addr != 0);
265	            if (directed_block) {
266	                Addr blkMask = ~(static_cast<Addr>(blockSize) - 1);
267	                Addr wantBlockAddr = target_block_addr & blkMask;
268	                for (CacheBlk* blk : validBlocks) {
269	                    if (tags->regenerateBlkAddr(blk) == wantBlockAddr) {
270	                        targetBlk = blk;
271	                        break;
272	                    }
273	                }
274	                if (!targetBlk && write_log) {
275	                    *(log_stream->stream()) << "Tick: " << curTick()
276	                        << ", Directed target_block_addr=0x" << std::hex
277	                        << target_block_addr << std::dec
278	                        << " NOT resident (no valid block at that address) — "
279	                        << "falling back to random block." << std::endl;
280	                }
281	            }
282	            if (!targetBlk) {
283	                std::uniform_int_distribution<int> blockDist(0, validBlocks.size() - 1);
284	                int randomIdx = blockDist(rng);
285	                targetBlk = validBlocks[randomIdx];
286	            }
287	
288	            Addr blockAddr = tags->regenerateBlkAddr(targetBlk);
289	
290	            uint8_t* data = targetBlk->data;
291	
292	            // §7.7 paired-sector 128B fault-domain proxy: find the 128B-aligned
293	            // paired partner block (blockAddr XOR 64B). The fault is applied to
294	            // BOTH sectors at the SAME byte offset. The partner must be VALID+
295	            // resident (else only the primary is faulted — logged honestly).
296	            // This models a 128B L3 fault domain spanning two 64B sectors. It is
297	            // a PROXY, not a cycle-exact Kunpeng L3 model (per plan §7.7/§3.1).
298	            CacheBlk* partnerBlk = nullptr;
299	            uint8_t* partnerData = nullptr;
300	            Addr partnerAddr = 0;
301	            if (paired_sector) {
302	                // The partner is the other 64B sector in the same 128B superline.
303	                Addr partnerBlockAddr = blockAddr ^ blockSize;  // toggle bit (log2(64)=6)
304	                for (CacheBlk* blk : validBlocks) {
305	                    if (tags->regenerateBlkAddr(blk) == partnerBlockAddr) {
306	                        partnerBlk = blk;
307	                        partnerData = blk->data;
308	                        partnerAddr = partnerBlockAddr;
309	                        break;
310	                    }
311	                }
312	                if (write_log && !partnerBlk) {
313	                    *(log_stream->stream()) << "Tick: " << curTick()
314	                        << ", PAIRED-SECTOR WARN: partner block 0x" << std::hex
315	                        << partnerBlockAddr << std::dec << " NOT resident — "
316	                        << "only primary sector faulted (128B domain incomplete)."
317	                        << std::endl;
318	                }
319	            }
320	
321	            // Directed byte offset (report §六.3 'fixed-to'): if set, pin the
322	            // fault to this byte within the block; else random.
323	            bool directed_byte = (target_byte_offset >= 0
324	                                  && target_byte_offset < (int)blockSize);
325	
326	            FaultType chosen_fault_type_enum = fault_type_enum;
327	            if (fault_type_enum == FaultType::Random) {
