    CHAOSCache::generateRandomMask(std::mt19937 &rng, int bits_to_change, unsigned size) {
        uint8_t mask = 0;
        std::uniform_int_distribution<int> bit_dist(0, size - 1);
        for (int i = 0; i < bits_to_change; i++) {
            mask |= (1ULL << bit_dist(rng));
        }
        return mask;
