namespace gem5
{

class CHAOSCache : public SimObject
{
  public:
    CHAOSCache(const CHAOSCacheParams& params);
    virtual ~CHAOSCache() {}

    // §5.8B tag-array fault, FALSE-HIT formulation (v2, learned from the
    // first verification round): directly rewriting the stored tag via
    // setTag made the block evict under an address the snoop filter never
    // tracked (WritebackDirty/CleanEvict of an untracked line panics in
    // snoop_filter.cc:144 — a SimulatorError, not a valid DUE outcome).
    // The FAULT MODEL the plan §2.3 actually specifies is "tag >=3-bit:
    // silent false-hit": a lookup for address A is answered by the block
    // of ANOTHER address B of the same set. We therefore model the fault
    // AT LOOKUP TIME: the injector records a per-set "false-hit alias"
    // (block B's way), and TaggedEntry::match() diverts lookups that
    // would have hit the corrupted tag to block B instead. The tag STORE
    // stays untouched, so evictions/writebacks remain protocol-consistent
    // (the line evicts under its REAL address); only the data SUPPLY is
    // wrong — exactly the SDC-relevant semantics.
    // Called from TaggedEntry::match() (via the chaosTagAlias hook in
    // tagged_entry.hh). Returns true if this lookup is being diverted
    // (false hit). Hot path: no alias registered -> false.
    bool chaosMatchDivert(Addr lookup_addr, bool lookup_secure,
                          Addr blk_tag, bool blk_secure,
                          bool orig_match) const;
    // Register the alias (called by injectMetadataFault for target_field
    // tag/tag_to_legal). set is the set of the corrupted block; way is
    // the WAY of the block whose DATA will be served instead.
    void chaosRegisterAlias(unsigned set, unsigned alias_way);
    void chaosClearAlias();

  private:
    // False-hit alias state: per-set {alias_way, valid}. A single alias
    // is registered per injection (single-fault discipline, G5).
    struct TagAlias { unsigned set; unsigned way; bool valid; };
    TagAlias tag_alias = {0, 0, false};
    // Whether the alias is a HARD divert (tag_to_legal F5: every lookup
    // to the corrupted tag's set-way range hits the alias block) or a
    // SOFT one (tag bit_flip: the corrupted tag no longer matches its
    // own lookups — modeled by clearing the divert for the corrupted
    // way's own address only). v2 simplification: both modes register
    // the alias; the corrupted block's own lookups MISS (refetch) and
    // the aliased lookups hit the wrong data.

